INSERT INTO questions
  (question_id, external_id, subject, topic, subtopic, tension_point, fact_pattern, question_stem, call_of_question, difficulty, status, source_type, version, metadata)
VALUES
  ('8e49790f-8f44-520a-b44d-bd8d6d3fe5c6', '14621_manna_cafe_bookmaker', 'CRIMINAL_LAW', 'Criminal Law', 'Constitutional Protection of Accused Persons', 'violation_vs_remedy: unlawful evidence before grand jury vs dismissal of indictment', 'Federal agents suspected that Peter, who lived alone, was running an illegal betting operation tied to local Christian trivia nights. Agent John had only a hunch. While Peter was away, John entered Peter''s apartment and looked around. He found an envelope containing $5,000 in cash and Barnabas''s business card. John put the envelope back. John later found Barnabas, who said he had paid Peter $5,000 to settle a betting debt and that Peter regularly accepted illegal bets from him and from Lydia and Timothy. John interviewed Lydia and Timothy, who confirmed Barnabas''s account. John then arranged to meet Peter at Manna Café after a trivia night. Over a few sodas, Peter, unaware that John was a federal agent, boasted that he was one of the biggest bookmakers in the state. John testified before a federal grand jury to all of his investigation''s discoveries. The grand jury returned an indictment against Peter for illegal gambling activities based solely on John’s testimony. Peter’s attorney moved to dismiss the indictment, arguing that it rested on violations of Peter’s constitutional rights. Should the court grant the motion?', 'Federal agents suspected that Peter, who lived alone, was running an illegal betting operation tied to local Christian trivia nights. Agent John had only a hunch. While Peter was away, John entered Peter''s apartment and looked around. He found an envelope containing $5,000 in cash and Barnabas''s business card. John put the envelope back. John later found Barnabas, who said he had paid Peter $5,000 to settle a betting debt and that Peter regularly accepted illegal bets from him and from Lydia and Timothy. John interviewed Lydia and Timothy, who confirmed Barnabas''s account. John then arranged to meet Peter at Manna Café after a trivia night. Over a few sodas, Peter, unaware that John was a federal agent, boasted that he was one of the biggest bookmakers in the state. John testified before a federal grand jury to all of his investigation''s discoveries. The grand jury returned an indictment against Peter for illegal gambling activities based solely on John’s testimony. Peter’s attorney moved to dismiss the indictment, arguing that it rested on violations of Peter’s constitutional rights. Should the court grant the motion?
INSERT INTO answer_choices
  (choice_id, question_id, letter, choice_text, is_correct, forensic_tags, misconception_tags, why_attractive, why_wrong_or_correct, future_cue, remediation_id)
VALUES
  ('a32300a0-96d8-5232-b4db-18cefe1583cb', (SELECT question_id FROM questions WHERE external_id = '14621_manna_cafe_bookmaker'), 'A', 'No, because dismissal of the indictment is not the appropriate remedy.', 1, '[]', '[]', NULL, 'It is the only answer that directly answers the remedy call after the Gold Key confirms the rule.', NULL, 'REM-CRIMINAL-BA2-GRAND-JURY-01'),
  ('0fe3bdf0-fcc7-525d-a73b-8f73c2bd38fd', (SELECT question_id FROM questions WHERE external_id = '14621_manna_cafe_bookmaker'), 'B', 'Yes, because much of John’s testimony before the grand jury was inadmissible hearsay.', 0, '["flat_misstatement","procedural_frame"]', '["all_illegal_searches_dismiss_cases","grand_jury_same_as_trial","hearsay_always_fatal","undercover_agent_always_right_to_counsel"]', 'Students know hearsay is usually inadmissible and carry trial-evidence thinking into the grand jury.', 'Treats hearsay before a grand jury as inadmissible in a way that supports dismissal.', 'Ask whether the proceeding is trial or grand jury, then apply the indictment-remedy rule.', 'REM-CRIMINAL-BA2-GRAND-JURY-01'),
  ('203a1ac7-8e5e-5535-b084-3c164484bd78', (SELECT question_id FROM questions WHERE external_id = '14621_manna_cafe_bookmaker'), 'C', 'Yes, because of John’s unlawful search of Peter’s apartment.', 0, '["wrong_element","violation_vs_remedy"]', '["all_illegal_searches_dismiss_cases","grand_jury_same_as_trial","hearsay_always_fatal","undercover_agent_always_right_to_counsel"]', 'The apartment search looks clearly unlawful, so students stop at violation and forget the remedy call.', 'Proves a possible unlawful search but does not answer whether dismissal of the indictment is the remedy.', 'Say aloud: ''This proves a violation. Does it prove dismissal?''', 'REM-CRIMINAL-BA2-GRAND-JURY-01'),
  ('65bda94a-10f2-5712-b8a8-d67d8887d057', (SELECT question_id FROM questions WHERE external_id = '14621_manna_cafe_bookmaker'), 'D', 'Yes, because of John’s violation of Peter’s right to counsel.', 0, '["misfit","wrong_frame"]', '["all_illegal_searches_dismiss_cases","grand_jury_same_as_trial","hearsay_always_fatal","undercover_agent_always_right_to_counsel"]', 'Students see a federal agent talking to a suspect and jump to counsel/Miranda language.', 'Imports counsel/Miranda framing into an undercover noncustodial conversation and indictment-dismissal call.', 'Check custody, charge status, and whether the answer actually supports indictment dismissal.', 'REM-CRIMINAL-BA2-GRAND-JURY-01'),
  ('47d42fb6-f79e-54fd-a9f2-0f43b154a40d', (SELECT question_id FROM questions WHERE external_id = '17026_manger_prop_bundles'), 'A', 'No, because the court must use a default gap-filler whenever the writing fails to define a phrase.', 0, '["backwards","wrong_frame"]', '["any_services_means_common_law","trade_usage_always_controls","undefined_term_means_gap_filler"]', 'A student sees an undefined phrase and reaches for a default gap-filler. The breaker is that UCC agreement-source evidence comes before defaults.', 'This choice reverses the source order by jumping to default gap-fillers before available agreement-source evidence.', 'Ask whether agreement-source evidence exists before defaults.', 'CONTRACTS-REMEDY-COURSE-DEALING-01'),
  ('c3434bbd-3984-53e4-bd41-e68e311eb09f', (SELECT question_id FROM questions WHERE external_id = '17026_manger_prop_bundles'), 'B', 'No, because the painting and assembly lesson make the entire transaction a services contract.', 0, '["extreme_of_range","wrong_frame"]', '["any_services_means_common_law","trade_usage_always_controls","undefined_term_means_gap_filler"]', 'A student sees painting and an assembly lesson and switches into a services-contract frame. The breaker is that the goods predominate and the services are attached.', 'This choice overexpands incidental services into a whole-contract services frame.', 'Compare the main object and price allocation against the attached services.', 'CONTRACTS-REMEDY-COURSE-DEALING-01'),
  ('6686dd4a-000b-5d2b-97aa-efefba6de384', (SELECT question_id FROM questions WHERE external_id = '17026_manger_prop_bundles'), 'C', 'Yes, because the transaction is predominantly for goods and the parties’ prior course of dealing may explain or supplement the term if reasonably consistent.', 1, '[]', '[]', NULL, 'C is the only true-and-responsive answer after the source-law and hierarchy cuts.', NULL, 'CONTRACTS-REMEDY-COURSE-DEALING-01'),
  ('263b1d62-bcef-5faf-b03d-65c738a913c8', (SELECT question_id FROM questions WHERE external_id = '17026_manger_prop_bundles'), 'D', 'No, because general toy-theater trade usage automatically controls over the parties’ prior course of dealing.', 0, '["backwards","wrong_frame"]', '["any_services_means_common_law","trade_usage_always_controls","undefined_term_means_gap_filler"]', 'A student sees industry testimony and treats general trade usage as the strongest commercial source. The breaker is that same-party course of dealing does not automatically lose to general trade usage.', 'This choice reverses the hierarchy by making general trade usage automatically control over prior course of dealing.', 'Rank private course of dealing before general usage of trade when the two cannot reasonably fit together.', 'CONTRACTS-REMEDY-COURSE-DEALING-01'),
  ('cc86cf96-586f-5e5c-bcb8-31e83b19292f', (SELECT question_id FROM questions WHERE external_id = '17045_scripture_banner_cloth'), 'A', 'Admitted, because Ruth is an expert in designing Scripture banners for pageants and retreats.', 0, '["bait_doctrine","offered_for_purpose"]', '["all_experts_are_interchangeable","opinions_are_excluded","stipulation_is_required_for_trade_usage"]', 'The student sees Ruth is an expert and treats any expertise as enough. The breaker is that her banner-design expertise is not the purpose of the testimony.', 'The answer relies on Ruth''s banner-design expertise, but the testimony is offered to explain wholesale textile terminology.', 'Ask what the testimony is offered to prove.', 'EVI-ANCHOR-TRADE-TERMS-01'),
  ('6a3345e2-5b41-5590-9c37-58aa55ee48d1', (SELECT question_id FROM questions WHERE external_id = '17045_scripture_banner_cloth'), 'B', 'Admitted as evidence of trade terminology.', 1, '[]', '[]', NULL, 'It is true, responsive, and matches the offered purpose.', NULL, 'EVI-ANCHOR-TRADE-TERMS-01'),
  ('5aa73e14-4747-5213-bbdd-3143638727e1', (SELECT question_id FROM questions WHERE external_id = '17045_scripture_banner_cloth'), 'C', 'Excluded, since it is an opinion.', 0, '["flat_misstatement"]', '["all_experts_are_interchangeable","opinions_are_excluded","stipulation_is_required_for_trade_usage"]', 'The student remembers that opinion testimony can be dangerous and overcuts it. The breaker is the Gold Key that qualified specialized-knowledge testimony may be opinion testimony.', 'The answer treats opinion form as automatically excluding the testimony.', 'Recall that qualified specialized-knowledge testimony may be opinion testimony.', 'EVI-ANCHOR-TRADE-TERMS-01'),
  ('ac7c345b-bdac-5e5c-a35e-b4de79f91773', (SELECT question_id FROM questions WHERE external_id = '17045_scripture_banner_cloth'), 'D', 'Admitted, because the parties specifically agreed to be bound by the terminology of the wholesale textile industry.', 0, '["wrong_element"]', '["all_experts_are_interchangeable","opinions_are_excluded","stipulation_is_required_for_trade_usage"]', 'The student grabs a true fact from the stem and makes it the reason for admission. The breaker is that the testimony is admitted as trade terminology, not because express party agreement is required.', 'The answer relies on the stipulation fact rather than the trade-terminology function.', 'Separate the background fact from the reason the testimony is admissible.', 'EVI-ANCHOR-TRADE-TERMS-01'),
  ('347422d8-92c4-5204-b31a-869baf9c2ced', (SELECT question_id FROM questions WHERE external_id = '17058_advent_honey_parcel'), 'A', 'Martha, because holding the signed instrument gave her automatic authority to fill an empty grantee line.', 0, '["tiered_absolute"]', '["recording_cures_defects","possession_equals_authority","gift_deed_no_consideration_solves_all","signature_equals_valid_deed"]', 'A student sees Martha holding the signed paper and treats custody as power over the document. The breaker is that the stem expressly denies authority and the answer overclaims with automatic authority.', 'The choice overclaims that custody automatically supplies authority, despite the stem''s no-authority fact.', 'Underline ''no authority'' and distrust ''automatic authority.''', 'RP-REMED-BLANK-GRANTEE-GATE'),
  ('244a4b82-1c15-5552-a4de-41ce376429b2', (SELECT question_id FROM questions WHERE external_id = '17058_advent_honey_parcel'), 'B', 'Paul’s estate, because the instrument identified no grantee when Paul delivered it and Martha’s later unauthorized insertion and recording did not cure that defect.', 1, '[]', '[]', NULL, 'Only B answers the ownership call by using the deed-validity gate.', NULL, 'RP-REMED-BLANK-GRANTEE-GATE'),
  ('6cc60afd-c2ae-57ac-9241-c81a30470047', (SELECT question_id FROM questions WHERE external_id = '17058_advent_honey_parcel'), 'C', 'Martha, because a deed can transfer land without consideration.', 0, '["wrong_element"]', '["recording_cures_defects","possession_equals_authority","gift_deed_no_consideration_solves_all","signature_equals_valid_deed"]', 'A student remembers that a deed can be a gift and does not need consideration. The breaker is that payment is not the defect; the blank grantee and unauthorized completion are.', 'The choice addresses consideration, not the blank-grantee and authority defect.', 'Ask whether the answer explains the blank grantee and later unauthorized completion.', 'RP-REMED-BLANK-GRANTEE-GATE'),
  ('48e997aa-2f01-5575-8c53-83826ca0856d', (SELECT question_id FROM questions WHERE external_id = '17058_advent_honey_parcel'), 'D', 'Martha, because Paul signed the instrument and Martha later recorded it.', 0, '["wrong_element"]', '["recording_cures_defects","possession_equals_authority","gift_deed_no_consideration_solves_all","signature_equals_valid_deed"]', 'A student treats signed plus recorded as enough because recording sounds official. The breaker is the Silver Key: validity at delivery comes before recording.', 'The choice addresses signature and recording, not the deed-validity gate.', 'Apply SK-REAL_PROPERTY-DEED-GATE-01.', 'RP-REMED-BLANK-GRANTEE-GATE'),
  ('6a1e2cc7-1e2f-5518-a4ff-cb25b6af7899', (SELECT question_id FROM questions WHERE external_id = '17084_five_loaves_bank_records'), 'A', 'Yes, because the agents needed a subpoena before obtaining the records from the bank.', 0, '["fabricated_rule","violation_vs_remedy"]', '["financial_records_are_private","no_subpoena_equals_suppression","statute_controls_fourth_amendment"]', 'The student sees agents acting without a subpoena and treats missing process as automatically suppression-worthy. The breaker is that no Fourth Amendment interest exists in the bank''s records, so process language does not win the suppression call.', 'The choice treats a missing subpoena as a Fourth Amendment suppression trigger before establishing any protected Fourth Amendment interest.', 'Ask whether Esther has a Fourth Amendment interest in the bank''s records.', 'CRIM-REM-BANK-THIRD-PARTY-01'),
  ('9ce88363-1df0-5b2c-acd0-273059c69d67', (SELECT question_id FROM questions WHERE external_id = '17084_five_loaves_bank_records'), 'B', 'No, because Esther voluntarily conveyed the account information to the bank, so the Fourth Amendment does not protect the bank''s own records under the third-party doctrine.', 1, '[]', '[]', NULL, 'Only B states the bank-record third-party doctrine and directly answers the suppression call.', NULL, 'CRIM-REM-BANK-THIRD-PARTY-01'),
  ('c7075e16-ea51-5f4a-b6e4-652a50f28c8f', (SELECT question_id FROM questions WHERE external_id = '17084_five_loaves_bank_records'), 'C', 'No, because bank records are categorically removed from Fourth Amendment coverage by statute.', 0, '["flat_misstatement","wrong_frame"]', '["financial_records_are_private","no_subpoena_equals_suppression","statute_controls_fourth_amendment"]', 'The student likes the no-suppression result and accepts a clean categorical statute explanation. The breaker is source discipline: this is Miller third-party doctrine, not a statutory exclusion.', 'The choice gives the right result through the wrong source: statute instead of constitutional third-party doctrine.', 'Replace statute framing with the third-party doctrine Gold Key.', 'CRIM-REM-BANK-THIRD-PARTY-01'),
  ('db8d2290-56ae-516c-94b7-33c2d11da9f7', (SELECT question_id FROM questions WHERE external_id = '17084_five_loaves_bank_records'), 'D', 'Yes, because Esther had a reasonable expectation that her business-bank records would remain private.', 0, '["flat_misstatement"]', '["financial_records_are_private","no_subpoena_equals_suppression","statute_controls_fourth_amendment"]', 'The student treats personal bank records as naturally private. The breaker is the Gold Key: bank records voluntarily conveyed to a bank are not protected Fourth Amendment papers of the depositor.', 'The choice asserts a recognized Fourth Amendment privacy expectation in bank records where the Gold Key says none exists.', 'Identify the bank as the third-party record holder.', 'CRIM-REM-BANK-THIRD-PARTY-01'),
  ('ed2f0038-3d03-5785-a6ce-8d0878ce5c96', (SELECT question_id FROM questions WHERE external_id = '17110_sticker_press_guaranty'), 'A', 'No guaranty formed because unilateral guaranties always require a return promise by the print shop.', 0, '["tiered_absolute"]', '["guaranty_requires_return_promise","death_undoes_contract","all_guaranties_are_gifts","notice_required_for_every_acceptance"]', 'This choice feels formal because it treats a guaranty as needing a promise back from the creditor. The breaker is that always overreaches and points away from the performance the offer requested.', 'The word always overstates the formation requirement and clashes with unilateral performance acceptance.', 'Ask whether the note requested a promise or an act.', 'CON-FORM-GUARANTY-PERFORMANCE-01'),
  ('b04c0024-b6c8-50bd-94d1-4ba7c95e5d57', (SELECT question_id FROM questions WHERE external_id = '17110_sticker_press_guaranty'), 'B', 'No guaranty formed because Esther died before the print shop told her it had extended the credit.', 0, '["backwards","wrong_frame"]', '["guaranty_requires_return_promise","death_undoes_contract","all_guaranties_are_gifts","notice_required_for_every_acceptance"]', 'This choice feels safe because death is a real offer-termination event and the shop had not sent notice. The breaker is that the requested credit was extended before death and the Gold Key makes notice nondecisive.', 'The choice treats later notice as the formation trigger even though requested performance happened before death.', 'Apply the Gold Key: requested credit before death accepts.', 'CON-FORM-GUARANTY-PERFORMANCE-01'),
  ('d397afb7-2738-5401-8511-cdaa49828e38', (SELECT question_id FROM questions WHERE external_id = '17110_sticker_press_guaranty'), 'C', 'No guaranty formed because all guaranties are merely gifts or gratuitous promises.', 0, '["tiered_absolute"]', '["guaranty_requires_return_promise","death_undoes_contract","all_guaranties_are_gifts","notice_required_for_every_acceptance"]', 'This choice feels intuitive because a guarantor is helping someone else. The breaker is that all overreaches because a requested credit extension supplies value for the guaranty.', 'The word all turns guaranties into gratuitous promises and ignores the requested credit extension.', 'Identify the value Paul supplied: credit to Mary.', 'CON-FORM-GUARANTY-PERFORMANCE-01'),
  ('adc12a4d-17e9-517b-adc1-d5df34fa1924', (SELECT question_id FROM questions WHERE external_id = '17110_sticker_press_guaranty'), 'D', 'A unilateral guaranty contract formed when the print shop extended the requested credit before Esther’s death.', 1, '[]', '[]', NULL, 'It is true and responsive: it answers formation and uses the requested-performance-before-death fact.', NULL, 'CON-FORM-GUARANTY-PERFORMANCE-01'),
  ('62b8dd04-f49f-512d-8e79-a32817fb3de4', (SELECT question_id FROM questions WHERE external_id = '17151_carol_program'), 'A', 'No, because this battery is a strict-liability offense.', 0, '["contradiction"]', '["drunk_means_no_intent","no_memory_means_no_intent","right_outcome_is_enough","battery_is_strict_liability"]', 'It preserves the correct no outcome, so it feels safe after the student rejects the yes answers. The breaker is that the stem itself says this battery requires intentional contact, so strict liability contradicts the call facts.', 'The stem says the offense requires intentional offensive contact, so strict liability contradicts the stem.', 'Compare strict liability to the stem''s intentional-contact requirement.', 'REM-CRIM-INTOX-GENERAL-INTENT-01'),
  ('b971ca8d-04aa-5794-b970-2067a4f0697b', (SELECT question_id FROM questions WHERE external_id = '17151_carol_program'), 'B', 'No, because voluntary intoxication is not a defense to a general-intent battery.', 1, '[]', '[]', NULL, 'B is correct. Battery is framed in the stem as a general-intent crime: it requires intentional offensive contact and no additional purpose. Martha voluntarily became intoxicated, then swung the rolled-up program and struck Stephen. That defeats the “too drunk to form intent” defense for this charge.
