  ('fa682f56-1aef-5f5f-a454-755e5cafbdf6', (SELECT question_id FROM questions WHERE external_id = '19904_psalm_orchard_foreclosure_notice'), 'C', 'deny Barnabas''s request.', 1, '[]', '[]', NULL, 'It is the only answer that addresses the missing notice/service threshold.', NULL, 'REM-RP-FORECLOSURE-NOTICE-01'),
  ('d52fdbac-da49-599f-8aa1-fb09ec824624', (SELECT question_id FROM questions WHERE external_id = '19904_psalm_orchard_foreclosure_notice'), 'D', 'order the sale of a fee interest.', 0, '["bait_doctrine","procedural_frame"]', '["visible_possessor_controls","future_interest_can_be_ignored","substantive_fee_answer_beats_process"]', 'The student knows a senior recorded mortgage can support foreclosure of the mortgaged fee and reaches the substantive result. The breaker is the Gold Key: sale scope comes only after the necessary parties receive notice.', 'The choice may describe the sale scope after proper procedure, but it skips the current notice/service defect.', 'Say: fee sale may be later; denial is now.', 'REM-RP-FORECLOSURE-NOTICE-01'),
  ('9c97ee61-3f73-5b43-8429-06817dc60d87', (SELECT question_id FROM questions WHERE external_id = '19982_manna_warehouse'), 'A', 'Clear-notice requirements apply only to criminal statutes.', 0, '["tiered_absolute"]', '["federal_money_blank_check","clear_notice_only_criminal","states_must_draft_conditions"]', 'The student remembers clear notice from criminal-law contexts. The breaker is that the Gold Key places clear notice in Spending Clause grants too.', 'The choice overlimits clear notice to criminal statutes and misses the Spending Clause clear-notice rule.', 'Treat clear notice as a Spending Clause grant condition when states accept federal funds.', 'REMED-CONLAW-SPENDING-CLEAR-NOTICE'),
  ('7a6fc7f1-8435-5a87-a57c-d73e863dc35a', (SELECT question_id FROM questions WHERE external_id = '19982_manna_warehouse'), 'B', 'Congress may impose any undisclosed grant condition after a state has accepted the funds.', 0, '["backwards"]', '["federal_money_blank_check","clear_notice_only_criminal","states_must_draft_conditions"]', 'The student treats federal money as permission for broad federal control. The breaker is that the state must know the condition before accepting the money.', 'The choice reverses the rule by permitting undisclosed post-acceptance grant conditions.', 'Ask whether the state knew this condition before taking the funds.', 'REMED-CONLAW-SPENDING-CLEAR-NOTICE'),
  ('5f157d98-35bb-5510-9a3e-469d7e425cd3', (SELECT question_id FROM questions WHERE external_id = '19982_manna_warehouse'), 'C', 'Spending conditions must give states clear notice so they can accept federal funds knowingly.', 1, '[]', '[]', NULL, 'It is the only answer that is both true under the Gold Key and responsive to the hidden-condition trigger.', NULL, 'REMED-CONLAW-SPENDING-CLEAR-NOTICE'),
  ('9781da93-190c-5892-a5b2-526ee32cc847', (SELECT question_id FROM questions WHERE external_id = '19982_manna_warehouse'), 'D', 'Spending conditions are valid only if the participating states draft them.', 0, '["fabricated_rule"]', '["federal_money_blank_check","clear_notice_only_criminal","states_must_draft_conditions"]', 'The student reaches for state sovereignty and gives states control over drafting. The breaker is that the actual requirement is clear congressional notice, not state authorship.', 'The choice invents a requirement that states draft Spending Clause conditions.', 'Reject actor requirements that the Gold Key does not contain.', 'REMED-CONLAW-SPENDING-CLEAR-NOTICE'),
  ('53bed762-ffce-5ea3-aac3-d9085e0f6794', (SELECT question_id FROM questions WHERE external_id = '20004_dove_tokens_manna_game'), 'A', 'Stephen wins unless Ruth proves impossibility or frustration of purpose.', 0, '["bait_doctrine","wrong_frame"]', '["estimate_equals_minimum","shutdown_requires_excuse","PER_blocks_later_facts"]', 'It turns business disruption into an excuse-doctrine question. The breaker is that the requirements term itself may leave Ruth with zero covered needs.', 'The choice jumps to excuse doctrines instead of answering the requirements-quantity call.', 'Ask whether Ruth had any covered requirements left.', 'CON-REQ-01'),
