  ('4921f050-04a5-58e7-bf7c-981d75700acc', (SELECT question_id FROM questions WHERE external_id = '20004_dove_tokens_manna_game'), 'C', 'The court may not consider Ruth''s cancellation evidence because it varies the written estimate under the parol evidence rule.', 0, '["backwards","wrong_frame"]', '["estimate_equals_minimum","shutdown_requires_excuse","PER_blocks_later_facts"]', 'It protects the written estimate with formal-sounding parol-evidence language. The breaker is that later cancellation evidence measures performance under the written requirements term.', 'The choice points the parol-evidence rule at later cancellation evidence.', 'Ask when the fact occurred and what it is offered to prove.', 'CON-REQ-01'),
  ('248753f5-52b4-5c38-92e0-48b44d868e89', (SELECT question_id FROM questions WHERE external_id = '20004_dove_tokens_manna_game'), 'D', 'Ruth may have zero requirements if she canceled the covered game line in good faith and did not shift the same token requirements elsewhere.', 1, '[]', '[]', NULL, 'Only D answers the quantity/good-faith question created by the requirements term.', NULL, 'CON-REQ-01'),
  ('135dd978-5c5f-56dc-9c17-a5bf8b43db47', (SELECT question_id FROM questions WHERE external_id = '20024_loaves_fishes_crate_count'), 'A', 'Yes, because inventory consultants are strictly liable for inaccurate count sheets.', 0, '["misfit","wrong_frame"]', '["all_foreseeable_readers_can_sue","professional_error_equals_strict_liability","economic_loss_never_recoverable"]', 'The student sees a professional error and wants automatic liability. The breaker is that the call asks negligence, not strict liability.', 'The choice changes a negligent-misrepresentation claim into a strict-liability shortcut.', 'Say: strict liability is a different frame.', 'REM-TORTS-NMISREP-01'),
  ('0f7257f5-7169-5766-8833-5945640004f8', (SELECT question_id FROM questions WHERE external_id = '20024_loaves_fishes_crate_count'), 'B', 'No, because Timothy was not within a known or limited class for a specific transaction.', 1, '[]', '[]', NULL, 'It is the only answer that tracks the targeted-use duty limit and the stem''s internal-use facts.', NULL, 'REM-TORTS-NMISREP-01'),
  ('38f58a46-68b4-5958-be9d-f210237f7ba0', (SELECT question_id FROM questions WHERE external_id = '20024_loaves_fishes_crate_count'), 'C', 'No, because pure economic loss is never recoverable for negligent misrepresentation.', 0, '["tiered_absolute"]', '["all_foreseeable_readers_can_sue","professional_error_equals_strict_liability","economic_loss_never_recoverable"]', 'The student wants the correct no-liability result and accepts a broad economic-loss slogan. The breaker is the absolute word ''never.''', 'The word ''never'' overstates the economic-loss rule.', 'Flinch at ''never'' and ask whether an exception category exists.', 'REM-TORTS-NMISREP-01'),
